glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
vec4 CCFragOutput (vec4 color) {
  return color;
}
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform Constant {
  vec4 _OutlineColor;
  vec4 _TexelSize;
  float _OutlineSize;
};
float checkOutline(vec2 baseUv, vec2 offsetUv, float minAlpha) {
  vec2 uv = baseUv + offsetUv * _TexelSize.xy * _OutlineSize;
  vec4 col = texture(cc_spriteTexture, uv);
  float a = col.a;
  float isEdge = step(uv.x, 0.0) + step(1.0, uv.x) + step(uv.y, 0.0) + step(1.0, uv.y);
  isEdge = step(1.0, isEdge);
  a *= (1.0 - isEdge);
  return min(a, minAlpha);
}
vec4 frag () {
  vec4 col = texture(cc_spriteTexture, v_uv);
  #if SHOW_OUTLINE
  float minAlpha = checkOutline(v_uv, vec2(1, 0), 1.0);
  minAlpha = checkOutline(v_uv, vec2(0, 1), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(-1, 0), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(0, -1), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(1, 1), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(-1, 1), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(-1, -1), minAlpha);
  minAlpha = checkOutline(v_uv, vec2(1, -1), minAlpha);
  minAlpha = step(minAlpha, 0.0);
  col.rgb = mix(col.rgb, _OutlineColor.rgb, minAlpha);
  #endif
  col *= v_color;
  return CCFragOutput(col);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

